INSERT INTO `achievement_reward_locale` (`ID`, `Locale`, `Subject`, `Text`) VALUES
(13, 'koKR', 'Poziom 80', 'Gratuluję wytrwałości, dzięki której udało ci się dotrwać do osiemdziesiątego sezonu przygód. Nie ma wątpliwości, że sprawa uwolnienia Azeroth od zła, które nas nęka, jest ci naprawdę bliska.$B$BI choć dotychczasowa droga była nie lada wyczynem, prawdziwa bitwa dopiero przed tobą.$B$BWalcz dalej!$B$BRhonin'),
(45, 'koKR', 'Kawał świata za tobą!', 'No, no, patrzcie państwo!$B$BA ja myślałem, że to ja się napatrzyłem w tej lodowej krainie! Stary krasnolud widzi to jak na dłoni: w twoich oczach płonie ogień odkrywcy.$B$BNoś ten tabard z dumą. Dzięki niemu twoi przyjaciele będą wiedzieć, kogo pytać o drogę, gdy przyjdzie pora!$B$BNie zatrzymuj się!$B$BBrann Miedziobrody'),
(614, 'koKR', 'Za Przymierze!', 'Na naszych ziemiach szaleje wojna. Tylko najdzielniejsi bohaterowie ośmielają się uderzyć w Hordę tam, gdzie boli ją najbardziej. Ty do nich należysz.$B$BCiosy, które $gzadałeś:zadałaś; przywódcom Hordy, otworzą nam drogę do ostatecznego szturmu. Horda ugnie się przed potęgą Przymierza.$B$BTwoje czyny nie pozostaną bez nagrody. Jedź naprzód z dumą!$B$B– Twój król'),
(619, 'koKR', 'Za Hordę!', 'W tych czasach wielkiego zamętu z niedoli powstają prawdziwi bohaterowie. Ty jesteś $gjednym:jedną; z nich.$B$BNadeszła wojna. Twoje wysiłki przysłużą się naszej sprawie w Azeroth. Twoje wielkie czyny zostaną nagrodzone. Przyjmij tę nagrodę od Orgrimmaru i jedź ku chwale.$B$BZa Hordę!$B$BWódz Thrall'),
(876, 'koKR', 'Mam cię na oku, dzieciaku.', 'Masz niezłą smykałkę do bitki na tej arenie. Zatrzymaj to. Noś z dumą. A teraz wracaj tam i pokaż im, jak to się robi!$B$BWujek Sal'),
(1021, 'koKR', 'Nie lada osiągnięcie', 'Nie mogłem nie zauważyć, jak piękną kolekcję tabardów udało ci się zgromadzić przez te wszystkie sezony. Równie dobrze możesz dołączyć do niej i ten. U mnie w szafie tylko zbiera kurz.'),
(1250, 'koKR', 'Nowy dom Śmierdziucha', 'Słyszałam, jak dobrze opiekujesz się naszymi futrzastymi przyjaciółmi. Mam nadzieję, że nie masz nic przeciwko, ale muszę znaleźć Śmierdziuchowi nowy dom. On po prostu nie chce się ładnie bawić z innymi.$B$BProszę, pamiętaj, żeby karmić go dwa razy dziennie. I, hm... ma słabość do czarnych kotów.$B$B– Breanni'),
(1681, 'koKR', 'Pozdrowienia z Darnassus', 'Twoje dokonania są doniosłe i sięgają daleko. W tych niespokojnych czasach Azeroth wiele zawdzięcza tym, którzy pragną oczyścić świat ze zła.$B$BTylko ci, którzy zadają sobie trud, by poznać nasze ziemie, rozumieją ofiarę poległych i męstwo naszych bohaterów. Ty do tych bohaterów należysz. Oby opowieści o twoich przygodach rozbrzmiewały jeszcze przez długie lata.$B$BW imieniu Przymierza dziękuję ci, $gMistrzu:Mistrzyni; wiedzy.'),
(1682, 'koKR', 'Pozdrowienia z Gromowych Urwisk', 'Wieści o twoich dokonaniach dotarły daleko. Nad naszymi ziemiami wyją wichry zamętu. Ci, którzy stawiają czoła złu, są naszą jedyną nadzieją.$B$BTylko ci, którzy wsłuchują się w wiatr, rozumieją, jaki dług spłacili nasi polegli bohaterowie, by chronić nasz lud. Oby $gbohater taki:bohaterka taka; jak ty $gżył:żyła; długo i $gsnuł:snuła; opowieści o swoich przygodach. Bo tylko wtedy będziemy pamiętać, jak wiele mamy powodów do wdzięczności.$B$BNasze uznanie jest głębokie, $gMistrzu:Mistrzyni; wiedzy.$B$BZa Hordę!$B$B– Kairn Krwawe Kopyto'),
(1956, 'koKR', 'Wyższa edukacja', 'Gratuluję ukończenia studiów nad „Szkołami magii tajemnej”. W uznaniu dla twojego zaangażowania załączam ten wyjątkowy tom, który dopełnia serię.$B$BSądzę, że ta księga okaże się dla ciebie szczególnie zajmująca. Ale to już pozostawiam tobie do odkrycia.$B$BZ poważaniem$B$BRhonin'),
(2096, 'koKR', 'Mistrz monet', 'Witam i gratuluję zebrania pełnego kompletu monet z Dalaranu! W nagrodę za cały ten trud załączam świeżo wybitą tytanową pieczęć Dalaranu. To wyjątkowa moneta, którą przyznajemy tylko najzagorzalszym kolekcjonerom.$B$BMam nadzieję, że ta szczególna nagroda sprawi ci radość. Należy ci się!$B$BZ poważaniem$BDżepetto Radobrzęk'),
(2136, 'koKR', 'Chwała bohatera', '$GCzempionie:Czempionko;,$B$Bdo Świątyni Żmijowego Spoczynku dotarły wieści o wielkich, bohaterskich czynach, których $gdokonałeś:dokonałaś; od przybycia do Północnej Grani.$B$BTwoja odwaga nie powinna pozostać bez uznania. Proszę, przyjmij ten dar w imieniu Aspektów. Razem uwolnimy Azeroth od zła, raz i na wieczność.$B$BAlexstraza Życiodajna'),
(2143, 'koKR', 'Na czele kawalerii', 'Nie mogłam nie zauważyć, jak dobrze radzisz sobie ze zwierzętami. Przy całym tym ruchu w okolicy interes kręci mi się lepiej niż kiedykolwiek. Czy nie $gzechciałbyś:zechciałabyś; zaopiekować się dla mnie tym albinotycznym smokowcem? Zwyczajnie brakuje mi w ciągu dnia wolnych chwil, by zadbać o wszystkie te zwierzęta. Twoja Mei'),
(2144, 'koKR', 'Raz za razem', 'Gdy w oddali dudnią wojenne bębny, mieszkańcom Azeroth łatwo zapomnieć o wszystkim, co życie ma do zaoferowania.$B$BTy jednak $gzachowałeś:zachowałaś; godność dobrych ras Azeroth, bo pamiętasz, o co walczymy. Nie świętować naszych zwycięstw to tylko inna postać klęski. Zapamiętaj to dobrze, $gbiesiadniku:biesiadniczko;.$B$BOby twoja pogoda ducha natchnęła innych,$B$BAlexstraza Życiodajna'),
(2145, 'koKR', 'Raz za razem', 'Gdy w oddali dudnią wojenne bębny, mieszkańcom Azeroth łatwo zapomnieć o wszystkim, co życie ma do zaoferowania.$B$BTy jednak $gzachowałeś:zachowałaś; godność dobrych ras Azeroth, bo pamiętasz, o co walczymy. Nie świętować naszych zwycięstw to tylko inna postać klęski. Zapamiętaj to dobrze, $gbiesiadniku:biesiadniczko;.$B$BOby twoja pogoda ducha natchnęła innych,$B$BAlexstraza Życiodajna'),
(2516, 'koKR', 'Jelonek do kochania', 'Witaj!$B$BRozumiem, że udało ci się zapewnić ciepły i kochający dom nawet temu urwisowi Śmierdziuchowi... Miałam nadzieję, że może $gzechciałbyś:zechciałabyś; przygarnąć jeszcze jedną zabłąkaną sierotkę?$B$BTen mały jelonek jest płochliwy, ale bez trudu zdobędziesz jego przyjaźń dzięki temu, co załączam: jego ulubionej lizawce solnej!$B$B– Breanni'),
(2536, 'koKR', 'Góra wierzchowców', 'Słyszałam, że twoje stajnie są już prawie tak okazałe jak moje. Imponujące! Może pomożemy sobie nawzajem... Mam o jednego smoczego jastrzębia za dużo i liczyłam, że dasz mu dom. Naturalnie wyszkolono go na wierzchowca, a nie na zwierzaka łowcy, i przekonasz się, że jest równie wierny i niestrudzony jak każdy inny rumak z mojej hodowli. $B Znów twoja, Mei'),
(2537, 'koKR', 'Góra wierzchowców', 'Słyszałam, że twoje stajnie są już prawie tak okazałe jak moje. Imponujące! Może pomożemy sobie nawzajem... Mam o jednego smoczego jastrzębia za dużo i liczyłam, że dasz mu dom. Naturalnie wyszkolono go na wierzchowca, a nie na zwierzaka łowcy, i przekonasz się, że jest równie wierny i niestrudzony jak każdy inny rumak z mojej hodowli. $B Znów twoja, Mei'),
(2796, 'koKR', 'Witamy w klubie Piwo Miesiąca!', '$N,$B$Bwitamy w klubie Piwo Miesiąca! Nasz klub istnieje po to, by dostarczać ci najlepsze piwa ze wszystkich krain.$B$BCo miesiąc nowe piwo trafi pocztą prosto do ciebie. Jeśli ci zasmakuje i zechcesz więcej, porozmawiaj z członkami klubu Piwo Miesiąca.$B$BJeszcze raz witamy w klubie, $N.$B$B– Klub Piwo Miesiąca'),
(2957, 'koKR', 'Chwała rajdowca Ulduaru', '$GDrogi:Droga; $N,$B$Bmam nadzieję, że u ciebie wszystko dobrze i że $gzdążyłeś:zdążyłaś; już dojść do siebie po naszych harcach w Ulduarze.$B$BMoje chłopaki z ekipy poszukiwaczy natknęły się na to biedne, na wpół żywe pisklę wierzchowego smokowca. To musiał być jakiś eksperyment żelaznych krasnoludów.$B$BPostawiliśmy malucha na nogi i przekonasz się, że wcale już nie jest taki mały! Nikt z nas nie zna się na ujeżdżaniu czegokolwiek poza baranami i mułami jucznymi, a że mieliśmy u ciebie dług za to, co się tam wydarzyło... Pomyśleliśmy, że może przyjmiesz go w prezencie.$B$BTwój$BBrann Miedziobrody'),
(2958, 'koKR', 'Heroiczne: Chwała rajdowca Ulduaru', '$GDrogi:Droga; $N,$B$Bmam nadzieję, że u ciebie wszystko dobrze i że $gzdążyłeś:zdążyłaś; już dojść do siebie po naszych harcach w Ulduarze.$B$BMoje chłopaki z ekipy poszukiwaczy natknęły się na to biedne, na wpół żywe pisklę wierzchowego smokowca. To musiał być jakiś eksperyment żelaznych krasnoludów.$B$BPostawiliśmy malucha na nogi i przekonasz się, że wcale już nie jest taki mały! Nikt z nas nie zna się na ujeżdżaniu czegokolwiek poza baranami i mułami jucznymi, a że mieliśmy u ciebie dług za to, co się tam wydarzyło... Pomyśleliśmy, że może przyjmiesz go w prezencie.$B$BTwój$BBrann Miedziobrody'),
(3478, 'koKR', 'Indyk, który uniknął półmiska', 'Dasz wiarę, że ten pulchny indyk przeżył listopad?$B$BSkoro wszystkich jego przyjaciół podano na obfitych stołach z żurawinowym chutney, chlebem z przyprawami i... ooo... robię się głodna. Ale mniejsza z tym! Został teraz zupełnie sam, więc liczyłam, że może zechcesz się nim zaopiekować. W moim sklepie zwyczajnie nie ma już miejsca!$B$BTylko trzymaj go, proszę, z dala od palenisk. Dziwnie mu się przy nich świecą oczy...$B$B– Breanni'),
(3656, 'koKR', 'Indyk, który uniknął półmiska', 'Dasz wiarę, że ten pulchny indyk przeżył listopad?\n\nSkoro wszystkich jego przyjaciół podano na obfitych stołach z żurawinowym chutney, farszem z chleba z przyprawami i... ooo... robię się głodna. Ale mniejsza z tym! Został teraz zupełnie sam, więc liczyłam, że może zechcesz się nim zaopiekować. W moim sklepie zwyczajnie nie ma już miejsca!\n\nTylko trzymaj go, proszę, z dala od palenisk. Dziwnie mu się przy nich świecą oczy...'),
(3857, 'koKR', 'Mistrz Wyspy Podboju', '$GCzcigodny:Czcigodna; $N,$B$Bza twoje czyny na Wyspie Podboju mam zaszczyt wręczyć ci ten tabard. Noś go z dumą.$B$BWielki komendant 7. Legionu'),
(3957, 'koKR', 'Mistrz Wyspy Podboju', '$GCzcigodny:Czcigodna; $N,$B$Bza twoje czyny na Wyspie Podboju mam zaszczyt wręczyć ci ten tabard. Noś go z dumą.$B$BNadrządca Agmar'),
(4079, 'koKR', 'Hołd dla nieśmiertelności', '$GDrogi:Droga; $N,$B$Bopowieści o twoim niedawnym występie w Próbie Wielkiego Krzyżowca będą powtarzane przez wieki. Gdy Krucjata Argentu wezwała największych czempionów Azeroth, by sprawdzili swój hart w ogniu Koloseum, wbrew wszystkiemu miałem nadzieję, że z bitewnego zamętu wyłonią się takie światła przewodnie jak ty i twoi towarzysze.$B$BBędziemy cię bardzo potrzebować w nadchodzącej bitwie z Królem Liszem. Ale dziś raduj się, świętuj swoje chwalebne dokonanie i przyjmij w darze jednego z naszych najwspanialszych koni bojowych. Gdy Plaga ujrzy jego chorągiew na horyzoncie, $gbohaterze:bohaterko;, jej koniec będzie bliski!$B$BZ wyrazami szacunku$BTirion Fordring'),
(4156, 'koKR', 'Hołd dla nieśmiertelności', '$GDrogi:Droga; $N,$B$Bopowieści o twoim niedawnym występie w Próbie Wielkiego Krzyżowca będą powtarzane przez wieki. Gdy Krucjata Argentu wezwała największych czempionów Azeroth, by sprawdzili swój hart w ogniu Koloseum, wbrew wszystkiemu miałem nadzieję, że z bitewnego zamętu wyłonią się takie światła przewodnie jak ty i twoi towarzysze.$B$BBędziemy cię bardzo potrzebować w nadchodzącej bitwie z Królem Liszem. Ale dziś raduj się, świętuj swoje chwalebne dokonanie i przyjmij w darze jednego z naszych najwspanialszych koni bojowych. Gdy Plaga ujrzy jego chorągiew na horyzoncie, $gbohaterze:bohaterko;, jej koniec będzie bliski!$B$BZ wyrazami szacunku$BTirion Fordring'),
(4478, 'koKR', 'P.U.G.', 'Droga, bardzo cierpliwa osobo,$B$Bchcemy docenić twój upór w przemierzaniu lochów z ludźmi, których pewnie nigdy wcześniej nie $gspotkałeś:spotkałaś;. Mamy nadzieję, że w tych losowych grupach udało ci się nawet pokazać paru żółtodziobom, co i jak.$B$BKrótko mówiąc: doszły nas słuchy, że lubisz pugi. Masz więc mopsa, czyli puga, do swojego puga, żeby dało się pugować podczas pugowania. Czy jakoś tak.$B$BŚciskamy$B$BTwoi przyjaciele z zespołu twórców WoW.'),
(4602, 'koKR', 'Chwała rajdowca Lodowej Korony', '$N,$B$Bw miarę jak wpływ Króla Lisza słabnie, niektóre z jego potężniejszych sług wyrywają się z jego uścisku.$B$BTa młoda samica żmija mrozu, którą schwytali moi ludzie, jest tego najlepszym przykładem. Ma własną wolę, i to aż nadto.$B$BJeden z moich ludzi stracił rękę, gdy ją ujeżdżał, ale teraz smoczyca całkiem nieźle znosi jeźdźców – o ile sami są wprawni i mają silną wolę.$B$BProszę, przyjmij tę wspaniałą bestię w darze od Rycerzy Hebanowego Miecza. Walka u twego boku w tej największej z bitew była zaszczytem.$B$BZ honorem$BDarion Mograine.'),
(4603, 'koKR', 'Chwała rajdowca Lodowej Korony', '$N,$B$Bw miarę jak wpływ Króla Lisza słabnie, niektóre z jego potężniejszych sług wyrywają się z jego uścisku.$B$BTa młoda samica żmija mrozu, którą schwytali moi ludzie, jest tego najlepszym przykładem. Ma własną wolę, i to aż nadto.$B$BJeden z moich ludzi stracił rękę, gdy ją ujeżdżał, ale teraz smoczyca całkiem nieźle znosi jeźdźców – o ile sami są wprawni i mają silną wolę.$B$BProszę, przyjmij tę wspaniałą bestię w darze od Rycerzy Hebanowego Miecza. Walka u twego boku w tej największej z bitew była zaszczytem.$B$BZ honorem$BDarion Mograine.'),
(4784, 'koKR', 'Kwatermistrzowie emblematów w Srebrnej Enklawie w Dalaranie', 'Twoje osiągnięcia w Północnej Grani nie przeszły bez echa, $gprzyjacielu:przyjaciółko;.$B$BZa zdobyte emblematy możesz kupić wyposażenie u kwatermistrzów emblematów w Dalaranie.$B$BZnajdziesz nas tam, w Srebrnej Enklawie, gdzie każdy rodzaj emblematu ma swojego kwatermistrza.$B$BCzekamy na twoje przybycie!'),
(4785, 'koKR', 'Kwatermistrzowie emblematów w Sanktuarium Słońcobójców w Dalaranie', 'Twoje osiągnięcia w Północnej Grani nie przeszły bez echa, $gprzyjacielu:przyjaciółko;.$B$BZa zdobyte emblematy możesz kupić wyposażenie u kwatermistrzów emblematów w Dalaranie.$B$BZnajdziesz nas tam, w Sanktuarium Słońcobójców, gdzie każdy rodzaj emblematu ma swojego kwatermistrza.$B$BCzekamy na twoje przybycie!');
